INSERT OR IGNORE INTO blog_posts (id, title, slug, date, category, excerpt, image, body, published, created_at, updated_at) VALUES (1, 'Ransomware : 7 réflexes essentiels pour protéger votre entreprise', 'ransomware-7-reflexes-essentiels-pour-proteger-votre-entreprise', '12 Juillet 2026', 'Cybersécurité', 'Les attaques par rançongiciel explosent en Afrique centrale. Découvrez les bonnes pratiques pour réduire votre exposition et réagir efficacement.', 'https://images.unsplash.com/photo-1550751827-4bd374c3f58b?auto=format&fit=crop&w=900&q=80', '', 1, '2026-08-02 15:22:50', '2026-08-02 15:22:50');
INSERT OR IGNORE INTO blog_posts (id, title, slug, date, category, excerpt, image, body, published, created_at, updated_at) VALUES (2, 'NIS2 et entreprises congolaises : ce qui change pour vous', 'nis2-et-entreprises-congolaises-ce-qui-change-pour-vous', '28 Juin 2026', 'Réglementation', 'La directive NIS2 étend son champ d''application. Comprenez les obligations qui s''appliquent à votre secteur et comment vous y préparer.', 'https://images.unsplash.com/photo-1563013544-824ae1b704d3?auto=format&fit=crop&w=900&q=80', '', 1, '2026-08-02 15:22:50', '2026-08-02 15:22:50');
INSERT OR IGNORE INTO blog_posts (id, title, slug, date, category, excerpt, image, body, published, created_at, updated_at) VALUES (3, 'Sensibilisation : comment la data aide vos équipes à se protéger', 'sensibilisation-comment-la-data-aide-vos-equipes-a-se-proteger', '05 Juin 2026', 'Formation', 'Les statistiques de phishing simulé révèlent vos points faibles humains. Comment transformer ces données en programme de formation efficace.', 'https://images.unsplash.com/photo-1562813733-b31f71025d54?auto=format&fit=crop&w=900&q=80', '', 1, '2026-08-02 15:22:50', '2026-08-02 15:22:50');
