INSERT OR IGNORE INTO trainings (id, slug, icon, title, category, level, format, duration, next_session, description, active, sort_order, created_at, updated_at) VALUES (1, 'fondamentaux-cybersecurite', 'ShieldCheck', 'Fondamentaux de la cybersécurité', 'Sensibilisation', 'Débutant', 'Présentiel', '2 jours', 'Session mensuelle', 'Comprendre les menaces, vulnérabilités, contrôles de base et bonnes pratiques de protection des systèmes d''information.', 1, 1, '2026-08-02 15:22:49', '2026-08-02 15:22:49');
INSERT OR IGNORE INTO trainings (id, slug, icon, title, category, level, format, duration, next_session, description, active, sort_order, created_at, updated_at) VALUES (2, 'iso-27001-lead-implementer', 'Lock', 'ISO 27001 Lead Implementer', 'Gouvernance', 'Avancé', 'Hybride', '5 jours', 'Sur inscription', 'Structurer un SMSI, conduire l''analyse de risques, produire les livrables clés et préparer l''organisation à la certification.', 1, 2, '2026-08-02 15:22:49', '2026-08-02 15:22:49');
INSERT OR IGNORE INTO trainings (id, slug, icon, title, category, level, format, duration, next_session, description, active, sort_order, created_at, updated_at) VALUES (3, 'audit-securite-si', 'FileSearch', 'Audit de sécurité SI', 'Audit', 'Intermédiaire', 'Présentiel', '3 jours', 'Trimestrielle', 'Préparer une mission d''audit, collecter les preuves, qualifier les écarts et restituer un rapport exploitable par la direction.', 1, 3, '2026-08-02 15:22:49', '2026-08-02 15:22:49');
INSERT OR IGNORE INTO trainings (id, slug, icon, title, category, level, format, duration, next_session, description, active, sort_order, created_at, updated_at) VALUES (4, 'test-intrusion-web', 'Bug', 'Test d''intrusion web', 'Technique', 'Avancé', 'Atelier', '4 jours', 'Sur inscription', 'Méthodologie de pentest applicatif, OWASP Top 10, exploitation contrôlée, priorisation des vulnérabilités et remédiation.', 1, 4, '2026-08-02 15:22:49', '2026-08-02 15:22:49');
INSERT OR IGNORE INTO trainings (id, slug, icon, title, category, level, format, duration, next_session, description, active, sort_order, created_at, updated_at) VALUES (5, 'securite-reseau-entreprise', 'Network', 'Sécurité réseau d''entreprise', 'Technique', 'Intermédiaire', 'Présentiel', '3 jours', 'Bimestrielle', 'Segmentation, pare-feu, durcissement, supervision, VPN et contrôle des accès sur les architectures réseau critiques.', 1, 5, '2026-08-02 15:22:49', '2026-08-02 15:22:49');
INSERT OR IGNORE INTO trainings (id, slug, icon, title, category, level, format, duration, next_session, description, active, sort_order, created_at, updated_at) VALUES (6, 'securite-cloud-devsecops', 'CloudCog', 'Sécurité cloud & DevSecOps', 'Cloud', 'Intermédiaire', 'Hybride', '3 jours', 'Sur inscription', 'Sécuriser les environnements cloud, les pipelines CI/CD, les conteneurs, les secrets et les déploiements applicatifs.', 1, 6, '2026-08-02 15:22:49', '2026-08-02 15:22:49');
INSERT OR IGNORE INTO trainings (id, slug, icon, title, category, level, format, duration, next_session, description, active, sort_order, created_at, updated_at) VALUES (7, 'reponse-incidents-gestion-crise', 'Siren', 'Réponse aux incidents & gestion de crise', 'SOC & Incident', 'Intermédiaire', 'Atelier', '2 jours', 'Mensuelle', 'Préparer les procédures, qualifier un incident, coordonner les équipes, communiquer en crise et capitaliser après l''événement.', 1, 7, '2026-08-02 15:22:49', '2026-08-02 15:22:49');
INSERT OR IGNORE INTO trainings (id, slug, icon, title, category, level, format, duration, next_session, description, active, sort_order, created_at, updated_at) VALUES (8, 'soc-analyst-niveau-1', 'Laptop', 'SOC analyst niveau 1', 'SOC & Incident', 'Débutant', 'Atelier', '4 jours', 'Sur inscription', 'Lire les alertes, enrichir les événements, appliquer les playbooks, escalader les cas et suivre les indicateurs opérationnels.', 1, 8, '2026-08-02 15:22:49', '2026-08-02 15:22:49');
INSERT OR IGNORE INTO trainings (id, slug, icon, title, category, level, format, duration, next_session, description, active, sort_order, created_at, updated_at) VALUES (9, 'protection-donnees-conformite-rgpd', 'BookOpenCheck', 'Protection des données & conformité RGPD', 'Conformité', 'Débutant', 'En ligne', '2 jours', 'Mensuelle', 'Cartographier les traitements, gérer les bases légales, organiser les droits des personnes et préparer la documentation conformité.', 1, 9, '2026-08-02 15:22:49', '2026-08-02 15:22:49');
INSERT OR IGNORE INTO trainings (id, slug, icon, title, category, level, format, duration, next_session, description, active, sort_order, created_at, updated_at) VALUES (10, 'preparation-ceh', 'Award', 'Préparation CEH', 'Certification', 'Avancé', 'Hybride', '5 jours', 'Sur inscription', 'Réviser les domaines clés de l''ethical hacking, consolider la pratique labo et préparer un plan de passage de certification.', 1, 10, '2026-08-02 15:22:49', '2026-08-02 15:22:49');
INSERT OR IGNORE INTO trainings (id, slug, icon, title, category, level, format, duration, next_session, description, active, sort_order, created_at, updated_at) VALUES (11, 'sensibilisation-phishing-hygiene-numerique', 'GraduationCap', 'Sensibilisation phishing & hygiène numérique', 'Sensibilisation', 'Débutant', 'En ligne', '1 jour', 'À la demande', 'Réduire les risques humains avec des réflexes concrets : phishing, mots de passe, MFA, données sensibles et signalement.', 1, 11, '2026-08-02 15:22:49', '2026-08-02 15:22:49');
INSERT OR IGNORE INTO trainings (id, slug, icon, title, category, level, format, duration, next_session, description, active, sort_order, created_at, updated_at) VALUES (12, 'gestion-risques-cyber', 'CheckCircle2', 'Gestion des risques cyber', 'Gouvernance', 'Intermédiaire', 'Présentiel', '3 jours', 'Trimestrielle', 'Identifier les actifs, évaluer les scénarios de risque, définir les mesures de traitement et suivre un tableau de bord cyber.', 1, 12, '2026-08-02 15:22:49', '2026-08-02 15:22:49');
